#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/node/tasks/setup-deps-node.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Install the Node dependencies, then report the outdated ones, and with audit = \"package-manager\" the vulnerable ones; --upgrade upgrades them"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--upgrade" help="upgrade the dependencies to the latest versions in their package.json ranges instead of installing from the lockfile"

import os
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

root = os.environ["MISE_PROJECT_ROOT"]

# Shipped with the node tool. Without a package.json, this is not a Node
# project, so the task does not apply and prints nothing.
if not os.path.isfile(f"{root}/package.json"):
  sys.exit(0)

# The selection is the folder that the sync generates for the tool. `mise x --
# which` is not the test, because it also finds a tool of the user-level config.
conf_d = f"{root}/.config/mise/conf.d"
has_pnpm = os.path.isdir(f"{conf_d}/pnpm")
has_aube = os.path.isdir(f"{conf_d}/aube")

# The bun tool owns the dependencies of a Bun repository, and it has no task.
if not has_pnpm and not has_aube and os.path.isdir(f"{conf_d}/bun"):
  sys.exit(0)

upgrade = os.environ.get("usage_upgrade") == "true"
if upgrade:
  helpers.print_header("Upgrading Node dependencies ...")
else:
  helpers.print_header("Installing Node dependencies ...")

if has_pnpm and has_aube:
  helpers.print_error("this repository selects both pnpm and aube.")
  helpers.print_warn(
    "- remove [tools.pnpm] or [tools.aube] from .config/bootstrap/tools.toml, then run mise run setup:configs"
  )
  sys.exit(1)
elif has_pnpm:
  package_manager = "pnpm"
elif has_aube:
  package_manager = "aube"
else:
  helpers.print_error("this repository has a package.json, and it selects no package manager.")
  helpers.print_warn(
    "- add [tools.pnpm] or [tools.aube] to .config/bootstrap/tools.toml, then run mise run setup:configs"
  )
  sys.exit(1)

# mise installs the package manager itself, so the task never runs a self-update.
# An upgrade stays inside the ranges of each package.json, and `--no-save` keeps
# the ranges as they are: only the lockfile changes. To keep a package at its
# locked version, list it in `update.ignoreDeps` of the workspace file.
if upgrade:
  result = helpers.tool(package_manager, "update", "--dir", root, "--recursive", "--no-save")
else:
  # The lockfile decides the versions; an install never changes it.
  result = helpers.tool(package_manager, "install", "--dir", root, "--frozen-lockfile")
if result.returncode != 0:
  sys.exit(result.returncode)

helpers.print_subheader("Checking for outdated Node dependencies ...")
# A report only: `outdated` exits 1 when a dependency is outdated.
helpers.tool(package_manager, "outdated", "--dir", root, "--recursive", "--long")

# The audit of the dependencies: `audit` of [tools.node]. With "osv-scanner"
# (the default), code:sec:30-osv-scanner scans the lockfile, and this task does
# no audit. With "package-manager", the package manager audits here too.
audit = helpers.tool_value("node", "audit", "osv-scanner")
if audit == "osv-scanner":
  sys.exit(0)
if audit != "package-manager":
  helpers.print_error(f"[tools.node] audit is {audit!r}, but it must be osv-scanner or package-manager.")
  sys.exit(2)

helpers.print_subheader("Auditing Node dependencies for known vulnerabilities ...")
# Exits 1 for a vulnerability at or above `audit.level` of the workspace file,
# and that stops the setup.
result = helpers.tool(package_manager, "audit", "--dir", root)
sys.exit(result.returncode)
